describe("trail merge detection", () => {
  let mockDb: Db

  beforeEach(() => {
    vi.clearAllMocks()
    mockDb = makeMockDb()
  })

  it("marks trail as merged when feature branch is fully merged into base", async () => {
    const trail = makeTrailRow({
      id: "trail-1",
      branch: "user/my-feature",
      base: "main",
      status: "open",
    })

    mockDb = makeMockDb([trail])

    // First call: branch merge check (true = merged), second call: beforeSha check (false = wasn't already merged)
    vi.mocked(githubModule.isBranchMergedInto)
      .mockResolvedValueOnce(true)
      .mockResolvedValueOnce(false)


    await processAllWebhookEvents("push", null, makePushPayload("main"), mockDb, fakeCache, fakeEnv)

    expect(githubModule.isBranchMergedInto).toHaveBeenCalledWith(
      "testorg/testrepo",
      "main",
      "user/my-feature",
      "fake-token",
    )

    expect(mockDb.trails.updateMetadata).toHaveBeenCalledTimes(1)
    const [, id, updateData] = vi.mocked(mockDb.trails.updateMetadata).mock.calls[0]
    expect(id).toBe("trail-1")
    expect(updateData).toMatchObject({
      status: "merged",
      merged_at: expect.any(String),
    })
  })

  it("stores non-distinct feature branch commits in canonical commit tables", async () => {
    vi.mocked(githubModule.fetchCommitStatsBatch).mockResolvedValue({
      data: new Map(),
      failedItems: [],
      errors: [],
    })

    await processAllWebhookEvents(
      "push",
      null,
      makePushPayload("feature-x", {
        commits: [
          {
            id: "non-distinct-sha",
            message: "Update branch",
            distinct: false,
            timestamp: "2026-03-19T12:00:00Z",
            url: "https://github.com/testorg/testrepo/commit/non-distinct-sha",
            author: { name: "Test Author", username: "testauthor" },
          },
        ],
      }),
      mockDb,
      fakeCache,
      fakeEnv,
    )

    expect(mockDb.checkpoints.upsertRepoCommitBatch).toHaveBeenCalledWith("repo-1", [
      expect.objectContaining({ commit_sha: "non-distinct-sha" }),
    ])
    expect(mockDb.checkpoints.upsertRepoBranchCommitBatch).toHaveBeenCalledWith(
      "repo-1",
      "feature-x",
      ["non-distinct-sha"],
    )
    expect(mockDb.checkpoints.upsertCommitBatch).not.toHaveBeenCalled()
  })

  it("does NOT mark trail when feature branch still has commits ahead", async () => {
    const trail = makeTrailRow({
      id: "trail-1",
      branch: "user/my-feature",
      base: "main",
      status: "open",
    })

    mockDb = makeMockDb([trail])
    vi.mocked(githubModule.isBranchMergedInto).mockResolvedValue(false)

    await processAllWebhookEvents("push", null, makePushPayload("main"), mockDb, fakeCache, fakeEnv)

    expect(githubModule.isBranchMergedInto).toHaveBeenCalledTimes(1)
    expect(mockDb.trails.updateMetadata).not.toHaveBeenCalled()
  })

  it("does NOT check merge when push is to a different branch than the trail's base", async () => {
    const trail = makeTrailRow({
      id: "trail-1",
      branch: "user/my-feature",
      base: "main",
      status: "open",
    })

    mockDb = makeMockDb([trail])

    // Push to "develop", but trail base is "main"
    await processAllWebhookEvents(
      "push",
      null,
      makePushPayload("develop"),
      mockDb,
      fakeCache,
      fakeEnv,
    )

    expect(githubModule.isBranchMergedInto).not.toHaveBeenCalled()
    expect(mockDb.trails.updateMetadata).not.toHaveBeenCalled()
  })

  it("skips trails already in merged status", async () => {
    const trail = makeTrailRow({
      id: "trail-1",
      branch: "user/my-feature",
      base: "main",
      status: "merged",
    })

    mockDb = makeMockDb([trail])

    await processAllWebhookEvents("push", null, makePushPayload("main"), mockDb, fakeCache, fakeEnv)

    expect(githubModule.isBranchMergedInto).not.toHaveBeenCalled()
    expect(mockDb.trails.updateMetadata).not.toHaveBeenCalled()
  })

  it("skips trails in closed status", async () => {
    const trail = makeTrailRow({
      id: "trail-1",
      branch: "user/my-feature",
      base: "main",
      status: "closed",
    })

    mockDb = makeMockDb([trail])

    await processAllWebhookEvents("push", null, makePushPayload("main"), mockDb, fakeCache, fakeEnv)

    expect(githubModule.isBranchMergedInto).not.toHaveBeenCalled()
    expect(mockDb.trails.updateMetadata).not.toHaveBeenCalled()
  })

  it("ignores special branches (entire/checkpoints)", async () => {
