    getPassingChecksGate({
      trail,
      mergeability,
      checksStatus,
      isChecksLoading,
      isChecksError,
      extraGates,
    }),
  )
  gates.push(getFindingsAddressedGate({ findings, isFindingsLoading, isFindingsError }))
  gates.push(
    getBranchUpToDateGate({
      trail,
      mergeability,
      onUpdateBranch,
      isUpdatingBranch,
      updateBranchErrorMessage,
    }),
  )

  return gates
}

