// Require Bearer token auth (for CLI/API clients using entire-core JWTs)
export const requireBearerAuth = createMiddleware<{
  Bindings: Env
  Variables: AuthenticatedVariables
}>(async (c, next) => {
  const authHeader = c.req.header("Authorization")

  if (!authHeader) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const parts = authHeader.split(" ")
  if (parts.length !== 2 || parts[0] !== "Bearer") {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const token = parts[1]
  const db = getDb(c.env)

  const coreConfig = getCoreBearerConfig(c.env)
  if (!coreConfig) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  let principal: Awaited<ReturnType<typeof validateCoreJwt>>
  try {
    principal = await validateCoreJwt(token, coreConfig, (githubId) =>
      db.users.findByGitHubId(githubId),
    )
  } catch (err) {
    if (isCoreJwtUnavailableError(err)) {
      return c.json({ error: "Authentication service unavailable" }, 503)
    }
    throw err
  }
  if (!principal) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  c.set("userId", principal.userId)
  c.set("tokenScope", principal.scope)

  await next()
})

/**
 * Waitlist gate for OAuth redirect routes (authOAuthRoutes group).
 *
 * Applied as group middleware; inspects the session cookie on every OAuth
 * browser-redirect request:
 * - No session cookie, or the cookie refers to an unknown/expired session →
 *   pass through (next()). Pre-auth flows have no session yet and must not be
 *   blocked. The core/callback handler creates the session itself, so the
 *   middleware sees no session at entry for that route too — it does its own
 *   waitlist redirect after creation.
 * - Authenticated session AND computeWaitlisted() returns true → redirect to
 *   FRONTEND_BASE_URL/waitlist.
 * - Authenticated session AND not waitlisted → next() (approved users proceed
 *   through connect/install flows).
 */
export const waitlistOAuthGate = createMiddleware<{
  Bindings: Env
}>(async (c, next) => {
  const sessionToken = getCookie(c, "session")
  if (!sessionToken) {
    await next()
    return
  }

  let session: Awaited<ReturnType<typeof getSession>>
  try {
    session = await getSession(c.env.ENTIRE_CACHE, sessionToken)
  } catch {
    // KV transient error — degrade gracefully and let the individual handler decide
    await next()
    return
  }

  if (!session) {
    await next()
    return
  }

  const waitlisted = await computeWaitlisted(
    c.env,
    getOrCreatePostHogClient(c.env),
    session.userId,
    sessionToken,
  )

  if (waitlisted) {
    return c.redirect(`${c.env.FRONTEND_BASE_URL}/waitlist`)
  }

  await next()
})

// Accept either session-cookie auth (with CSRF for mutating methods) or
// Bearer token auth. We intentionally delegate to the existing middlewares so
// session and bearer semantics stay identical to the rest of the app.
export const requireAuthOrBearer = createMiddleware<{
  Bindings: Env
  Variables: AuthenticatedVariables
}>(async (c, next) => {
  const authHeader = c.req.header("Authorization")

  if (authHeader?.startsWith("Bearer ")) {
    return requireBearerAuth(c, next)
  }

  return requireAuth(c, next)
})

// Require admin privileges (must be used after requireAuth)
export const requireAdmin = createMiddleware<{
  Bindings: Env
  Variables: Variables
}>(async (c, next) => {
  const userId = c.get("userId")
  const db = getDb(c.env)
  const user = await nullIfInvalidUuid(db.users.findById(userId))

  if (!user || !isAdmin(c.env, user.is_admin ?? false)) {
    return c.json({ error: "Forbidden" }, 403)
  }

  await next()
})

