 *  FK re-enable runs in `finally` so a failed DELETE can't strand a connection with
 *  FK_CHECKS=0, which would silently mask FK violations in a subsequent test. */
export async function resetMySQLDatabase(db: Kysely<DB>): Promise<void> {
  await sql`SET FOREIGN_KEY_CHECKS = 0`.execute(db)
  try {
