+import type { TrailRow } from "./db/db-types"
+import type { PullRequestState } from "./github"
+
+const TERMINAL_TRAIL_STATUSES = new Set(["merged", "closed"])
+
+function sameRepoFullName(left: string | null, right: string): boolean {
+  return Boolean(left && left.toLowerCase() === right.toLowerCase())
+}
+
 // Resolve a trail's effective base branch, falling back to the repo's default
 // branch and finally to "main". Single source of truth for the fallback chain
 // shared between the trails and cache trail-detail endpoints — both compute
 // checkpoint exclusion and branch comparisons against this value.
 export function resolveBaseBranch(row: { base: string }, repo: { default_branch: string }): string {
   return row.base || repo.default_branch || "main"
 }
+
+export function isTerminalTrailStatus(status: string): boolean {
+  return TERMINAL_TRAIL_STATUSES.has(status)
+}
+
+export function isPullRequestStateForTrail(
+  prState: PullRequestState | null,
+  repoFullName: string,
+  trail: Pick<TrailRow, "branch">,
+): prState is PullRequestState {
+  if (!prState || prState.state !== "open" || !trail.branch) return false
+  if (!prState.base.ref) return false
+  return (
+    prState.head.ref === trail.branch &&
+    sameRepoFullName(prState.head.repo.full_name, repoFullName) &&
+    sameRepoFullName(prState.base.repo.full_name, repoFullName)
+  )
+}
+
+export type ActiveTrailBaseResolution = {
+  base: string
+  source: "pull_request" | "trail"
+  prState: PullRequestState | null
+}
+
+export async function resolveActiveTrailBase(args: {
+  repoFullName: string
+  repo: { default_branch: string }
+  trail: Pick<TrailRow, "base" | "branch" | "gh_pr_id" | "status">
+  accessToken: string
+  fetchPullRequestState: (
+    repoFullName: string,
+    prNumber: number,
+    accessToken: string,
+  ) => Promise<PullRequestState | null>
+}): Promise<ActiveTrailBaseResolution> {
+  const fallback = resolveBaseBranch(args.trail, args.repo)
+
+  if (!args.trail.gh_pr_id || !args.trail.branch || isTerminalTrailStatus(args.trail.status)) {
+    return { base: fallback, source: "trail", prState: null }
+  }
+
+  const prState = await args.fetchPullRequestState(
+    args.repoFullName,
+    args.trail.gh_pr_id,
+    args.accessToken,
+  )
+  if (!isPullRequestStateForTrail(prState, args.repoFullName, args.trail)) {
+    return { base: fallback, source: "trail", prState }
+  }
+
+  return { base: prState.base.ref, source: "pull_request", prState }
+}
